parameters.query:
update bot_profiles set deleted_at = now(), deleted_reason = $2
where profile_id = $1
returning profile_id, app_user_id, channel, deleted_reason;

update subscribers set status = 'expired'
where app_user_id = $1 and status = 'trialing'
returning app_user_id, $2::text as profile_id, $3::text as channel, $4::text as deleted_reason;

