function validateBase(resp) {
  if (!resp || resp.error) return { ok: false, reason: 'fetch_error: ' + JSON.stringify(resp && resp.error) };
  if (resp.status !== 'done') return { ok: false, reason: 'bad_status: ' + JSON.stringify(resp && resp.status) };
  const profiles = (resp.profiles === null || resp.profiles === undefined) ? [] : resp.profiles;
  if (!Array.isArray(profiles)) return { ok: false, reason: 'profiles_not_array' };
  return { ok: true, profiles: profiles };
}

const waResp = $('List WA Profiles').first().json;
const tgResp = $('List TG Profiles').first().json;
const waCheck = validateBase(waResp);
const tgCheck = validateBase(tgResp);

const rows = $input.all().map(function (i) { return i.json; });

// Empty-list floor (review C2, guard 2): a well-formed but EMPTY live list, while the
// registry holds >=1 alive row for that channel, is treated the SAME as an invalid
// fetch -- skip, never mass-retire on a suspicious-looking empty response. Mirrors the
// orphan sweep's own "never delete on ambiguity" philosophy; without this, a genuinely
// wrong-but-well-formed empty response would retire EVERY alive row for that channel in
// one pass -- the exact fail-dangerous polarity flip the orphan sweep avoids.
const registryCountByChannel = {};
for (const row of rows) {
  registryCountByChannel[row.channel] = (registryCountByChannel[row.channel] || 0) + 1;
}

function applyEmptyListFloor(check, channel) {
  if (!check.ok) return check;
  if (check.profiles.length === 0 && (registryCountByChannel[channel] || 0) > 0) {
    return { ok: false, reason: 'empty_list_floor: live list empty but registry holds ' + registryCountByChannel[channel] + ' alive row(s)' };
  }
  return check;
}

const waFinal = applyEmptyListFloor(waCheck, 'whatsapp');
const tgFinal = applyEmptyListFloor(tgCheck, 'telegram');

const liveSets = {};
if (waFinal.ok) { liveSets.whatsapp = new Set(waFinal.profiles.map(function (p) { return String(p.profile_id || '').trim(); })); }
if (tgFinal.ok) { liveSets.telegram = new Set(tgFinal.profiles.map(function (p) { return String(p.profile_id || '').trim(); })); }

const baseValid = { whatsapp: waFinal.ok, telegram: tgFinal.ok };
const baseSkipReason = { whatsapp: waFinal.ok ? null : waFinal.reason, telegram: tgFinal.ok ? null : tgFinal.reason };

// Pass 1: would this row be retired, if nothing capped it?
function wouldRetire(row) {
  const channel = row.channel;
  if (!baseValid[channel]) return false;
  const live = liveSets[channel];
  return !(live && live.has(String(row.profile_id || '').trim()));
}

const wouldRetireByChannel = {};
for (const row of rows) {
  if (wouldRetire(row)) {
    wouldRetireByChannel[row.channel] = (wouldRetireByChannel[row.channel] || 0) + 1;
  }
}

// PROPORTIONAL RETIRE CAP (Task 15b, the Task 12 review's pre-flip requirement).
// The empty-list floor above only catches a FULLY empty live list. Wappi's
// profile/all/get documents no pagination parameters at all and its response carries
// no envelope (no total/page/next/has_more, verified 2026-08-25 against both bases and
// against the published WhatsApp API docs), so a SILENTLY TRUNCATED list -- one page of
// a list that grew past some undocumented server-side limit -- is indistinguishable
// from a complete one, and every row past the cut would look "absent from Wappi" and be
// retired. A retirement is irreversible in effect (it frees the channel slot and
// detaches the profile from metering), so this branch refuses to act at all whenever
// the diff looks implausibly large for that base:
//
//     cap = max(2, 50% of that base's alive registry rows); would-be > cap => skip base
//
// The max(2, ...) floor keeps small, ordinary cleanups working (1 or 2 stale rows are
// retired even when they are 100% of a tiny registry -- that is the normal single-bot
// case, not a truncation signature); the 50% term is what a truncation or an outage
// trips. A capped base is skipped for the WHOLE run, same as skip_invalid_fetch, and
// the counts are carried in the reason so the execution log says exactly what it saw.
const RETIRE_CAP_FLOOR = 2;
const capReason = {};
for (const channel of Object.keys(registryCountByChannel)) {
  if (!baseValid[channel]) continue;
  const alive = registryCountByChannel[channel];
  const cap = Math.max(RETIRE_CAP_FLOOR, alive * 0.5);
  const would = wouldRetireByChannel[channel] || 0;
  if (would > cap) {
    capReason[channel] = 'retire_cap: would retire ' + would + ' of ' + alive +
      ' alive registry row(s) on ' + channel + ', cap ' + cap +
      ' = max(' + RETIRE_CAP_FLOOR + ', 50%) -- base skipped this run';
  }
}

return rows.map(function (row) {
  const channel = row.channel;
  const would = wouldRetire(row);
  let action, reason;
  if (!baseValid[channel]) {
    action = 'skip_invalid_fetch';
    reason = baseSkipReason[channel];
  } else if (capReason[channel]) {
    action = 'skip_retire_cap';
    reason = capReason[channel];
  } else if (!would) {
    action = 'keep';
    reason = null;
  } else {
    action = 'retire';
    reason = 'liveness';
  }
  return { json: Object.assign({}, row, { action: action, reason: reason, baseValid: baseValid[channel], wouldRetire: would }) };
});

